/* ============================================================================
 * BEHAVIORTREE.JS — Hierarchical Behavior Tree Engine (js/libs/behaviortree.min.js)
 * Implements Selector, Sequence, Decorator, Inverter, Cooldown, Condition,
 * and Action nodes with blackboard context & active-node telemetry.
 * ============================================================================ */
(function (global) {
    'use strict';

    const Status = Object.freeze({
        SUCCESS: 'SUCCESS',
        FAILURE: 'FAILURE',
        RUNNING: 'RUNNING'
    });

    class BaseNode {
        constructor(config = {}) {
            this.name = config.name || this.constructor.name;
            this.children = config.nodes || config.children || [];
        }
        tick(blackboard) {
            return Status.SUCCESS;
        }
    }

    class Selector extends BaseNode {
        constructor(config = {}) {
            super(config);
        }
        tick(blackboard) {
            for (let i = 0; i < this.children.length; i++) {
                const child = this.children[i];
                const status = child.tick(blackboard);
                if (status !== Status.FAILURE) {
                    if (blackboard && !blackboard.activeBTNode) {
                        blackboard.activeBTNode = child.name;
                    }
                    return status;
                }
            }
            return Status.FAILURE;
        }
    }

    class Sequence extends BaseNode {
        constructor(config = {}) {
            super(config);
        }
        tick(blackboard) {
            for (let i = 0; i < this.children.length; i++) {
                const child = this.children[i];
                const status = child.tick(blackboard);
                if (status !== Status.SUCCESS) {
                    return status;
                }
            }
            if (blackboard) {
                blackboard.activeBTNode = this.name;
            }
            return Status.SUCCESS;
        }
    }

    class Decorator extends BaseNode {
        constructor(config = {}) {
            super(config);
            this.node = config.node || (this.children && this.children[0]) || null;
        }
    }

    class Inverter extends Decorator {
        tick(blackboard) {
            if (!this.node) return Status.FAILURE;
            const status = this.node.tick(blackboard);
            if (status === Status.SUCCESS) return Status.FAILURE;
            if (status === Status.FAILURE) return Status.SUCCESS;
            return Status.RUNNING;
        }
    }

    class CooldownDecorator extends Decorator {
        constructor(config = {}) {
            super(config);
            this.cooldown = config.cooldown ?? 0.5;
            this._lastTriggered = -Infinity;
        }
        tick(blackboard) {
            if (!this.node) return Status.FAILURE;
            const now = (blackboard && blackboard.nowSec) ?? (performance.now() * 0.001);
            if (now - this._lastTriggered < this.cooldown) {
                return Status.FAILURE;
            }
            const status = this.node.tick(blackboard);
            if (status === Status.SUCCESS || status === Status.RUNNING) {
                this._lastTriggered = now;
            }
            return status;
        }
    }

    class Condition extends BaseNode {
        constructor(config = {}) {
            super(config);
            this.check = config.check || config.run || (() => false);
        }
        tick(blackboard) {
            return this.check(blackboard) ? Status.SUCCESS : Status.FAILURE;
        }
    }

    class Action extends BaseNode {
        constructor(config = {}) {
            super(config);
            this.run = config.run || (() => Status.SUCCESS);
        }
        tick(blackboard) {
            const res = this.run(blackboard);
            const finalStatus = (res === true)
                ? Status.SUCCESS
                : (res === false ? Status.FAILURE : (res || Status.SUCCESS));
            if (finalStatus !== Status.FAILURE && blackboard) {
                blackboard.activeBTNode = this.name;
            }
            return finalStatus;
        }
    }

    class Tree {
        constructor(config = {}) {
            this.name = config.name || 'RootBehaviorTree';
            this.root = config.tree || config.root || null;
            this.blackboard = config.blackboard || {};
        }
        step(customBlackboard = null) {
            const bb = customBlackboard || this.blackboard;
            bb.activeBTNode = null;
            if (!this.root) return Status.FAILURE;
            return this.root.tick(bb);
        }
    }

    global.BehaviorTree = {
        Status,
        SUCCESS: Status.SUCCESS,
        FAILURE: Status.FAILURE,
        RUNNING: Status.RUNNING,
        BaseNode,
        Selector,
        Sequence,
        Decorator,
        Inverter,
        CooldownDecorator,
        Condition,
        Action,
        Task: Action,
        Tree,
        BehaviorTree: Tree
    };
})(window);
